import asyncio
import os
import queue
import threading
from typing import Any, AsyncIterable, AsyncIterator, Optional

import azure.cognitiveservices.speech as speechsdk


class StreamingSpeechToText:
    def __init__(
        self,
        *,
        sample_rate_hz: int = 16000,
        channels: int = 1,
        language: str = "en-US",
        speech_key: Optional[str] = None,
        speech_region: Optional[str] = None,
    ) -> None:
        self.sample_rate_hz = sample_rate_hz
        self.channels = channels
        self.language = language
        self.speech_key = speech_key or os.environ["AZURE_SPEECH_KEY"]
        self.speech_region = speech_region or os.environ["AZURE_SPEECH_REGION"]

    async def transcribe(
        self,
        audio_chunks: AsyncIterable[bytes],
    ) -> AsyncIterator[dict[str, Any]]:
        speech_config = speechsdk.SpeechConfig(
            subscription=self.speech_key,
            region=self.speech_region,
        )
        speech_config.speech_recognition_language = self.language
        speech_config.set_property(
            speechsdk.PropertyId.SpeechServiceConnection_InitialSilenceTimeoutMs,
            "60000",
        )
        speech_config.set_property(
            speechsdk.PropertyId.SpeechServiceConnection_EndSilenceTimeoutMs,
            "1500",
        )

        audio_format = speechsdk.audio.AudioStreamFormat(
            samples_per_second=self.sample_rate_hz,
            bits_per_sample=16,
            channels=self.channels,
        )
        push_stream = speechsdk.audio.PushAudioInputStream(stream_format=audio_format)
        audio_config = speechsdk.audio.AudioConfig(stream=push_stream)

        recognizer = speechsdk.SpeechRecognizer(
            speech_config=speech_config,
            audio_config=audio_config,
        )

        loop = asyncio.get_running_loop()
        results: queue.Queue[dict[str, Any]] = queue.Queue()
        done = threading.Event()
        stopped = threading.Event()

        def put_result(payload: dict[str, Any]) -> None:
            results.put(payload)

        def on_recognizing(evt: speechsdk.SpeechRecognitionEventArgs) -> None:
            text = evt.result.text or ""
            if text:
                put_result(
                    {
                        "type": "interim",
                        "text": text,
                        "offset": evt.result.offset,
                        "duration": evt.result.duration,
                    }
                )

        def on_recognized(evt: speechsdk.SpeechRecognitionEventArgs) -> None:
            if evt.result.reason == speechsdk.ResultReason.RecognizedSpeech:
                text = evt.result.text or ""
                if text:
                    put_result(
                        {
                            "type": "final",
                            "text": text,
                            "offset": evt.result.offset,
                            "duration": evt.result.duration,
                        }
                    )
            elif evt.result.reason == speechsdk.ResultReason.NoMatch:
                put_result({"type": "nomatch"})

        def on_canceled(evt: speechsdk.SpeechRecognitionCanceledEventArgs) -> None:
            put_result(
                {
                    "type": "error",
                    "reason": str(evt.reason),
                    "error_details": evt.error_details,
                }
            )
            done.set()

        def on_session_stopped(_: Any) -> None:
            done.set()
            stopped.set()

        recognizer.recognizing.connect(on_recognizing)
        recognizer.recognized.connect(on_recognized)
        recognizer.canceled.connect(on_canceled)
        recognizer.session_stopped.connect(on_session_stopped)

        await asyncio.to_thread(recognizer.start_continuous_recognition)

        async def writer() -> None:
            try:
                async for chunk in audio_chunks:
                    if chunk:
                        await asyncio.to_thread(push_stream.write, chunk)
            finally:
                await asyncio.to_thread(push_stream.close)

        writer_task = asyncio.create_task(writer())

        try:
            while True:
                if done.is_set() and results.empty():
                    break
                try:
                    item = await loop.run_in_executor(None, results.get, True, 0.1)
                    yield item
                    if item.get("type") == "error":
                        break
                except queue.Empty:
                    if writer_task.done() and not stopped.is_set():
                        await asyncio.to_thread(recognizer.stop_continuous_recognition)
        finally:
            try:
                await writer_task
            finally:
                if not stopped.is_set():
                    await asyncio.to_thread(recognizer.stop_continuous_recognition)
